import unittest
from config import read_timeout
from client import request_timeout
class Contract(unittest.TestCase):
    def test_zero(self): self.assertEqual(read_timeout({"timeout_ms":0}), 0)
    def test_default(self): self.assertEqual(read_timeout({}), 1000)
    def test_units(self): self.assertEqual(request_timeout({"timeout_ms":250}), .25)
    def test_default_units(self): self.assertEqual(request_timeout({}), 1)
    def test_invalid(self):
        for value in [-1, True, "1", None]:
            with self.assertRaises(ValueError): read_timeout({"timeout_ms":value})

